 static System.Collections.Generic.IEnumerable<DependencyObject> BrandDescendants(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var next in BrandDescendants(child))yield return next;}}
 static void Contrast(){Func<string,double>lum=hex=>{var c=(Color)ColorConverter.ConvertFromString(hex);Func<byte,double>channel=b=>{var v=b/255d;return v<=.04045?v/12.92:Math.Pow((v+.055)/1.055,2.4);};return .2126*channel(c.R)+.7152*channel(c.G)+.0722*channel(c.B);};var rows=new List<string>();foreach(var pair in new[]{new[]{"#101014","#FF2F86"},new[]{"#101014","#FF438F"},new[]{"#101014","#F22A78"},new[]{"#242027","#C985A4"}}){var a=lum(pair[0]);var b=lum(pair[1]);var ratio=(Math.Max(a,b)+.05)/(Math.Min(a,b)+.05);Check(ratio>=4.5,"staff text contrast "+ratio.ToString("F2"));rows.Add(string.Join(" ",pair)+" "+ratio.ToString("F3"));}File.WriteAllLines(Path.Combine(output,"contrast.txt"),rows);}
