 class Live:ILiveViewService
 {
  public int Starts,Stops,Active,MaxActive,Readers,MaxReaders;int sequence;readonly byte[][]frames;
  public Live(){frames=new byte[2][];for(int i=0;i<2;i++){var v=new DrawingVisual();using(var g=v.RenderOpen())g.DrawRectangle(i==0?Brushes.Pink:Brushes.Purple,null,new Rect(0,0,320,240));var b=new RenderTargetBitmap(320,240,96,96,PixelFormats.Pbgra32);b.Render(v);var e=new JpegBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var m=new MemoryStream()){e.Save(m);frames[i]=m.ToArray();}}}
  public Task StartAsync(string id,CancellationToken t){Starts++;Active++;MaxActive=Math.Max(MaxActive,Active);if(Active>1)throw new Exception("Overlapping live ownership");return Task.CompletedTask;}
  public async Task<LiveViewFrame>GetFrameAsync(string id,CancellationToken t){Readers++;MaxReaders=Math.Max(MaxReaders,Readers);try{await Task.Delay(25,t);return new LiveViewFrame{ImageData=frames[(sequence++)%2],Width=320,Height=240,TimestampUtc=DateTime.UtcNow};}finally{Readers--;}}
  public Task StopAsync(string id,CancellationToken t){Check(Readers==0,"reader drained before SDK stop");Stops++;Active--;Check(Active>=0,"SDK stop has an owner");return Task.CompletedTask;}public Task FocusAsync(string id,int x,int y,CancellationToken t)=>Task.CompletedTask;
 }
